const treatments=[
['Fisioterapia','Recuperar movimento também é recuperar independência.','A fisioterapia atua na avaliação, prevenção e tratamento de alterações que podem causar dor, perda de mobilidade, fraqueza e limitações funcionais. O atendimento respeita sua condição e sua evolução ao longo do tratamento.','3bbc7ab9-8d5d-4889-bebd-6d7461a0864b.webp','Atendimento individual de fisioterapia'],
['Osteopatia','O corpo precisa ser compreendido como um conjunto.','A Osteopatia utiliza avaliação clínica e técnicas manuais para investigar alterações de mobilidade e funcionamento que podem estar relacionadas aos sintomas. O objetivo é compreender além do local onde a dor aparece.','da40e96f-0214-49cc-b39a-ac835337b0d6.webp','Rodrigo durante atendimento com técnicas manuais'],
['Dor crônica','Quando a dor permanece, é preciso olhar além do sintoma.','Conviver com dor durante meses ou anos pode modificar movimento, sono, trabalho e a confiança no próprio corpo. O cuidado começa com uma avaliação do quadro e das limitações, buscando estratégias para melhorar função, movimento e qualidade de vida.','77da5266-ba85-459d-a8e8-f1ea82af8ab4.webp','Avaliação e cuidado individualizado'],
['Reabilitação vestibular','Mais segurança para o seu equilíbrio.','Tontura e episódios de vertigem podem interferir nas atividades do dia a dia. A Reabilitação Vestibular utiliza avaliação e exercícios específicos para auxiliar pacientes com alterações relacionadas ao equilíbrio e ao sistema vestibular. Cada caso precisa ser avaliado individualmente.','05_consultorio.webp','Consultório para avaliação individual'],
['ATM e DTM','Cuidado com a mandíbula, a musculatura e o movimento.','As Disfunções Temporomandibulares podem afetar a articulação e os músculos da mastigação. A fisioterapia pode fazer parte do cuidado de sintomas como dor na mandíbula, estalos, dificuldade de movimentar a boca e tensão muscular, de acordo com a avaliação.','06_maca_e_identidade.webp','Espaço para avaliação e atendimento'],
['Pilates','Movimento com orientação, controle e propósito.','O Pilates pode ajudar no desenvolvimento de força, mobilidade, equilíbrio e consciência corporal. Pode fazer parte de uma estratégia de prevenção ou da continuidade da reabilitação, respeitando as condições de cada pessoa.','1a130db1-945a-4971-b2fa-4e70c22e0636.webp','Rodrigo orientando exercício de Pilates']
];
const questions=[['Preciso saber qual tratamento preciso antes de agendar?','Não. A avaliação é justamente o momento de compreender seu quadro e identificar quais estratégias podem ser indicadas para suas necessidades.'],['Fisioterapia serve apenas para quem sofreu uma lesão?','Não. A fisioterapia também pode atuar em diferentes situações envolvendo dor, limitação de movimento, reabilitação e prevenção.'],['O que é Osteopatia?','A Osteopatia utiliza avaliação e técnicas manuais para observar mobilidade e funcionamento de diferentes estruturas do corpo, buscando compreender fatores que podem estar relacionados aos sintomas apresentados pelo paciente.'],['O que é Reabilitação Vestibular?','É uma abordagem voltada para pessoas que apresentam alterações relacionadas ao equilíbrio e ao sistema vestibular, como alguns quadros de tontura e vertigem.'],['Fisioterapia pode ajudar em problemas de ATM?','Em determinados quadros de Disfunção Temporomandibular, a fisioterapia pode fazer parte do tratamento, especialmente quando existem alterações musculares, articulares e funcionais.'],['A clínica trabalha com dor crônica?','Sim. Pacientes com dores persistentes podem passar por avaliação para compreender as características do quadro e definir possibilidades de acompanhamento.'],['Como faço para agendar?','O agendamento pode ser realizado diretamente pelo WhatsApp da clínica. Use o botão de contato para conversar com a equipe e consultar a disponibilidade.']];
if (!document.querySelector('#faq-list').children.length) questions.forEach(([q,a])=>{const d=document.createElement('details');d.name='duvidas';d.innerHTML=`<summary>${q}</summary><p>${a}</p>`;document.querySelector('#faq-list').append(d);});
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');function closeMenu(){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');}menu.addEventListener('click',()=>{const open=nav.classList.toggle('is-open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
const dialog=document.querySelector('#gallery-dialog');document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#gallery-full').src=b.dataset.image;document.querySelector('#gallery-full').alt=b.dataset.caption;document.querySelector('#gallery-caption').textContent=b.dataset.caption;dialog.showModal();}));document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
